import android.content.Context
import com.artflow.studio.core.pixels.PixelBuffer
import com.artflow.studio.core.render.StrokeRasterizer
import com.artflow.studio.data.local.ProjectStorage
import com.artflow.studio.data.repository.canvas.CanvasRepositoryImpl
import com.artflow.studio.domain.model.brush.BrushParams
import com.artflow.studio.domain.model.brush.DualBrush
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.ExperimentalCoroutinesApi
import kotlinx.coroutines.test.UnconfinedTestDispatcher
import kotlinx.coroutines.test.resetMain
import kotlinx.coroutines.test.runTest
import kotlinx.coroutines.test.setMain
import org.mockito.Mockito.mock
import java.security.MessageDigest
import kotlin.math.abs

private const val WIDTH = 512
private const val HEIGHT = 128
private val RED = 0xFFFF0000.toInt()
private val BLUE = 0xFF0000FF.toInt()

private fun hex(color: Int): String = "%08x".format(color)

private fun hash(pixels: IntArray): String {
    val digest = MessageDigest.getInstance("SHA-256")
    for (pixel in pixels) for (shift in intArrayOf(24, 16, 8, 0)) digest.update((pixel ushr shift).toByte())
    return digest.digest().joinToString("") { "%02x".format(it.toInt() and 255) }
}

private fun diff(label: String, expected: IntArray, actual: IntArray) {
    var max = 0
    var changed = 0
    var beyondRounding = 0
    var where = -1
    for (i in expected.indices) {
        var largest = 0
        for (shift in intArrayOf(24, 16, 8, 0)) {
            largest = maxOf(largest, abs(((expected[i] ushr shift) and 255) - ((actual[i] ushr shift) and 255)))
        }
        if (largest > 0) changed++
        if (largest > 2) beyondRounding++
        if (largest > max) { max = largest; where = i }
    }
    println("$label changed=$changed beyond2=$beyondRounding maxChannel=$max at=${where % WIDTH},${where / WIDTH} expected=${if (where < 0) "none" else hex(expected[where])} actual=${if (where < 0) "none" else hex(actual[where])}")
    println("$label expectedSHA=${hash(expected)} actualSHA=${hash(actual)}")
}

private suspend fun prepare(): CanvasRepositoryImpl {
    val repo = CanvasRepositoryImpl(ProjectStorage(mock(Context::class.java)))
    repo.createCanvas(WIDTH, HEIGHT, 72)
    check(repo.setLayerPixels(repo.getActiveLayerId(), PixelBuffer.filled(WIDTH, HEIGHT, RED), "Fixture"))
    repo.setStrokeColor(BLUE)
    return repo
}

@OptIn(ExperimentalCoroutinesApi::class)
fun main() = runTest {
    Dispatchers.setMain(UnconfinedTestDispatcher(testScheduler))
    val plain = BrushParams(size = 20f, spacing = 0.25f, pressureToSize = 0f, pressureToOpacity = 0f, smoothing = 0f)
    val wet = plain.copy(wetMix = 0.1f, pull = 1f)
    val variants = listOf(
        "wet_dual" to wet.copy(dual = DualBrush(plain)),
        "wet_solo_live_control" to wet,
        "dry_dual_control" to plain.copy(pull = 1f, dual = DualBrush(plain)),
    )
    try {
        for ((name, brush) in variants) {
            val repo = prepare()
            val oracle = prepare()
            val wholeBounds = prepare()
            try {
                val layer = repo.getActiveLayerId()
                val original = requireNotNull(repo.layerPixels(layer)).pixels.copyOf()
                val depth = repo.undoDepth
                val mark = repo.historyMark
                check(requireNotNull(repo.compositePreviewFrame()).dirty == null)
                val stroke = repo.beginStroke(30.5f, 60.5f, 1f, brush, layer, timestamp = 1000L)
                val expectedStroke = oracle.beginStroke(30.5f, 60.5f, 1f, brush, oracle.getActiveLayerId(), timestamp = 1000L)
                check(requireNotNull(wholeBounds.compositePreviewFrame()).dirty == null)
                val boundedStroke = wholeBounds.beginStroke(30.5f, 60.5f, 1f, brush, wholeBounds.getActiveLayerId(), timestamp = 1000L)
                println("CASE $name liveEligible=${StrokeRasterizer.canDrawLive(requireNotNull(repo.activeStroke(stroke)))}")
                var lastFull = IntArray(0)
                var lastFrame = IntArray(0)
                for ((index, x) in listOf(190.5f, 350.5f).withIndex()) {
                    repo.continueStroke(stroke, x, 60.5f, 1f, timestamp = 1016L + index * 16L)
                    oracle.continueStroke(expectedStroke, x, 60.5f, 1f, timestamp = 1016L + index * 16L)
                    wholeBounds.continueStroke(boundedStroke, x, 60.5f, 1f, timestamp = 1016L + index * 16L)
                    val frame = requireNotNull(repo.compositePreviewFrame())
                    lastFrame = frame.buffer.pixels.copyOf()
                    lastFull = requireNotNull(repo.compositePreview()).pixels.copyOf()
                    println("FRAME $name index=$index dirty=${frame.dirty}")
                    diff("$name frame$index", lastFull, lastFrame)
                    for (sampleX in listOf(180, 185, 190, 195, 200, 220, 250, 300, 345)) {
                        val i = 60 * WIDTH + sampleX
                        println("PIXEL $name frame$index x=$sampleX full=${hex(lastFull[i])} frame=${hex(lastFrame[i])}")
                    }
                    check(original.contentEquals(requireNotNull(repo.layerPixels(layer)).pixels))
                    check(repo.undoDepth == depth && repo.historyMark == mark)
                }
                oracle.endStroke(expectedStroke)
                val committed = requireNotNull(oracle.layerPixels(oracle.getActiveLayerId())).pixels.copyOf()
                diff("$name full_vs_no_preview_commit", committed, lastFull)
                diff("$name frame_vs_no_preview_commit", committed, lastFrame)
                // With no intermediate in-stroke frame, the ordinary cache requests the whole
                // stroke's bounds. This uses the real crop path, not a changed renderer.
                val boundedFrame = requireNotNull(wholeBounds.compositePreviewFrame())
                println("WHOLE_BOUNDS $name dirty=${boundedFrame.dirty}")
                diff("$name whole_bounds_vs_no_preview_commit", committed, boundedFrame.buffer.pixels)
                check(committed.contentEquals(boundedFrame.buffer.pixels))
                repo.cancelStroke(stroke)
                check(original.contentEquals(requireNotNull(repo.layerPixels(layer)).pixels))
                check(original.contentEquals(requireNotNull(repo.compositePreviewFrame()).buffer.pixels))
                check(repo.undoDepth == depth && repo.historyMark == mark)
                println("HISTORY $name previewAndCancelOriginal=true undoDepth=$depth mark=$mark")
            } finally { repo.dispose(); oracle.dispose(); wholeBounds.dispose() }
        }
    } finally { Dispatchers.resetMain() }
}

