private fun start(repo: CanvasRepositoryImpl, params: BrushParams = wet, all: Boolean = true): Long {
    val id = repo.beginStroke(30.5f, 60.5f, 1f, params, repo.getActiveLayerId(), timestamp = 1000L)
    repo.continueStroke(id, 190.5f, 60.5f, 1f, timestamp = 1016L)
    if (all) repo.continueStroke(id, 350.5f, 60.5f, 1f, timestamp = 1032L)
    return id
}

private fun edit(repo: CanvasRepositoryImpl, layer: Long = repo.getActiveLayerId()): Long {
    val id = repo.beginStroke(300.5f, 60.5f, 1f, dryEdit, layer, timestamp = 2000L)
    repo.continueStroke(id, 330.5f, 60.5f, 1f, timestamp = 2016L)
    return id
}

private suspend fun sealed() {
    val repo = prepare()
    val oracle = prepare()
    try {
        requireNotNull(repo.compositePreviewFrame())
        val first = start(repo)
        requireNotNull(repo.compositePreviewFrame())
        repo.sealStrokeSegment(first)
        println("SEALED before dirty=${requireNotNull(repo.compositePreviewFrame()).dirty}")
        val second = edit(repo)
        val frame = requireNotNull(repo.compositePreviewFrame())
        val full = requireNotNull(repo.compositePreview())
        println("SEALED after dirty=${frame.dirty}")
        diff("sealed_wet_then_dry_frame", full.pixels, frame.buffer.pixels)
        oracle.endStroke(start(oracle))
        oracle.endStroke(edit(oracle))
        val expected = requireNotNull(oracle.layerPixels(oracle.getActiveLayerId())).pixels
        diff("sealed_wet_full_vs_commit", expected, full.pixels)
        repo.endStroke(first)
        repo.endStroke(second)
        diff("sealed_wet_committed_vs_oracle", expected, requireNotNull(repo.layerPixels(repo.getActiveLayerId())).pixels)
    } finally { repo.dispose(); oracle.dispose() }
}

private suspend fun mirrored() {
    val repo = prepare()
    val oracle = prepare()
    try {
        for (target in listOf(repo, oracle)) {
            target.setSymmetry(mirror)
            check(target.setLayerDrawingAssist(target.getActiveLayerId(), true))
        }
        requireNotNull(repo.compositePreviewFrame())
        val id = start(repo, all = false)
        val first = requireNotNull(repo.compositePreviewFrame())
        println("MIRRORED first dirty=${first.dirty}")
        diff("mirrored_first", requireNotNull(repo.compositePreview()).pixels, first.buffer.pixels)
        repo.continueStroke(id, 350.5f, 60.5f, 1f, timestamp = 1032L)
        val frame = requireNotNull(repo.compositePreviewFrame())
        val full = requireNotNull(repo.compositePreview())
        println("MIRRORED tail dirty=${frame.dirty}")
        diff("mirrored_tail", full.pixels, frame.buffer.pixels)
        oracle.endStroke(start(oracle))
        diff("mirrored_full_vs_commit", requireNotNull(oracle.layerPixels(oracle.getActiveLayerId())).pixels, full.pixels)
    } finally { repo.dispose(); oracle.dispose() }
}

private suspend fun historical(onLowerLayer: Boolean, wetHistorical: Boolean) {
    val repo = prepare()
    val oracle = prepare()
    val historyBrush = if (wetHistorical) wet else plain.copy(opacity = 0.1f)
    val activeBrush = if (wetHistorical) dryEdit else wet
    try {
        for (target in listOf(repo, oracle)) {
            val layer = target.getActiveLayerId()
            val history = Stroke(
                id = 9001L,
                points = listOf(30.5f, 190.5f, 350.5f).mapIndexed { index, x -> StrokePoint(x, 60.5f, timestamp = 1000L + index * 16, color = BLUE) },
                brushParams = historyBrush, layerId = layer, color = BLUE, timestamp = 1000L,
            )
            check(target.replaceLayerStrokes(layer, listOf(history)))
            if (onLowerLayer) target.addLayer("Dry edit")
        }
        val label = "historical_${if (wetHistorical) "wet" else "dry"}_${if (onLowerLayer) "lower" else "same"}"
        val original = requireNotNull(repo.compositePreviewFrame()).buffer.pixels.copyOf()
        val id: Long
        if (wetHistorical) {
            id = edit(repo)
        } else {
            id = start(repo, activeBrush, all = false)
            requireNotNull(repo.compositePreviewFrame())
            repo.continueStroke(id, 350.5f, 60.5f, 1f, timestamp = 1032L)
        }
        val frame = requireNotNull(repo.compositePreviewFrame())
        val full = requireNotNull(repo.compositePreview())
        println("HISTORY $label dirty=${frame.dirty}")
        diff(label + "_frame", full.pixels, frame.buffer.pixels)
        val expectedStroke = if (wetHistorical) edit(oracle) else start(oracle, activeBrush)
        oracle.endStroke(expectedStroke)
        val expected = requireNotNull(oracle.compositePreview()).pixels
        diff(label + "_full_vs_commit", expected, full.pixels)
        repo.cancelStroke(id)
        diff(label + "_cancel", original, requireNotNull(repo.compositePreviewFrame()).buffer.pixels)
    } finally { repo.dispose(); oracle.dispose() }
}

@OptIn(ExperimentalCoroutinesApi::class)
