    Dispatchers.setMain(UnconfinedTestDispatcher(testScheduler))
    try {
        sealed()
        mirrored()
        historical(onLowerLayer = false, wetHistorical = true)
        historical(onLowerLayer = true, wetHistorical = true)
        historical(onLowerLayer = false, wetHistorical = false)
    } finally { Dispatchers.resetMain() }
